#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main(void) {
    int contador = 10;
    printf("padre: pid=%d contador=%d\n", getpid(), contador);
    fflush(stdout);

    pid_t pid = fork();            /* acá nace el hijo: copia del padre */
    if (pid < 0) { perror("fork"); return 1; }

    if (pid == 0) {                /* esto lo ejecuta SOLO el hijo */
        contador = 99;             /* toca su copia, no la del padre */
        printf("hijo:  pid=%d padre=%d contador=%d (antes del exec)\n",
               getpid(), getppid(), contador);
        fflush(stdout);
        char *args[] = { "sh", "-c",
            "echo \"sh:    pid=$$ padre=$PPID argumento=$1\"; exit 3",
            "sh", "hola-argumento", NULL };
        execvp("sh", args);        /* reemplaza el programa; si vuelve, falló */
        perror("execvp");
        _exit(127);
    }

    int estado;
    waitpid(pid, &estado, 0);      /* el padre espera al hijo */
    if (WIFEXITED(estado))
        printf("padre: el hijo %d terminó con código de salida %d\n",
               pid, WEXITSTATUS(estado));
    printf("padre: contador sigue en %d\n", contador);
    return 0;
}
